using namespace std;
const int MAX_N = int(1e6) + 100;
int a[MAX_N];
int sort(int l,int r,int k) {
    while(l <= r) {
        while ((l <= r) && (a[l] >> k & 1)) l++;
        while ((l <= r) && (!(a[r] >> k & 1))) r--;
        if (l <= r) swap(a[l++], a[r--]);
    }
    return r;
}
int main() {
    int n, j, ans=0;
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
    for (int i = 31; i >= 0; i--)
        if ((j = sort(1, n, i)) >= 2) {
            ans = ans | 1 << i;
            n = j;
        }
    printf("%d\n", ans);
    return 0;
}
